package zebra

type Solution struct {
	DrinksWater string
	OwnsZebra   string
}

var nationalities = [5]string{"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"}

// permutations of 0..4
func perms(n int) [][]int {
	res := [][]int{}
	var gen func(cur []int, used bool)
	cur := make([]int, 0, n)
	used := false
	_ = used
	usedMask := 0
	var rec func()
	rec = func() {
		if len(cur) == n {
			p := make([]int, n)
			copy(p, cur)
			res = append(res, p)
			return
		}
		for i := 0; i < n; i++ {
			if usedMask&(1<<uint(i)) == 0 {
				usedMask |= 1 << uint(i)
				cur = append(cur, i)
				rec()
				cur = cur[:len(cur)-1]
				usedMask &= ^(1 << uint(i))
			}
		}
	}
	_ = gen
	rec()
	return res
}

// pos converts a permutation (item -> house) into house->index mapping inverse:
// given perm p where p[i] is the house of item i, return idx such that item at
// house h. Simpler: index[v] = house of value v.
func index(p []int) [5]int {
	var idx [5]int
	for h, v := range p {
		idx[v] = h
	}
	return idx
}

func nextTo(a, b int) bool {
	d := a - b
	if d < 0 {
		d = -d
	}
	return d == 1
}

const (
	red, green, ivory, yellow, blue = 0, 1, 2, 3, 4
)

const (
	englishman, spaniard, ukrainian, norwegian, japanese = 0, 1, 2, 3, 4
)

const (
	water, coffee, tea, orangeJuice, milk = 0, 1, 2, 3, 4
)

const (
	oldGold, kools, chesterfields, luckyStrike, parliaments = 0, 1, 2, 3, 4
)

const (
	dog, snails, fox, horse, zebra = 0, 1, 2, 3, 4
)

func SolvePuzzle() Solution {
	colorPerms := perms(5)
	natPerms := perms(5)
	drinkPerms := perms(5)
	smokePerms := perms(5)
	petPerms := perms(5)

	for _, c := range colorPerms {
		ci := index(c) // color -> house
		// 6. green immediately right of ivory
		if ci[green] != ci[ivory]+1 {
			continue
		}
		for _, n := range natPerms {
			ni := index(n)
			// 2. Englishman lives in the red house
			if ni[englishman] != ci[red] {
				continue
			}
			// 10. Norwegian lives in the first house
			if ni[norwegian] != 0 {
				continue
			}
			// 15. Norwegian lives next to the blue house
			if !nextTo(ni[norwegian], ci[blue]) {
				continue
			}
			for _, d := range drinkPerms {
				di := index(d)
				// 4. Coffee is drunk in the green house
				if di[coffee] != ci[green] {
					continue
				}
				// 9. Milk is drunk in the middle house
				if di[milk] != 2 {
					continue
				}
				// 5. Ukrainian drinks tea
				if di[tea] != ni[ukrainian] {
					continue
				}
				for _, s := range smokePerms {
					si := index(s)
					// 8. Kools are smoked in the yellow house
					if si[kools] != ci[yellow] {
						continue
					}
					// 13. Lucky Strike smoker drinks orange juice
					if si[luckyStrike] != di[orangeJuice] {
						continue
					}
					// 14. Japanese smokes Parliaments
					if si[parliaments] != ni[japanese] {
						continue
					}
					for _, p := range petPerms {
						pi := index(p)
						// 3. Spaniard owns the dog
						if pi[dog] != ni[spaniard] {
							continue
						}
						// 7. Old Gold smoker owns snails
						if pi[snails] != si[oldGold] {
							continue
						}
						// 11. Chesterfields next to the man with the fox
						if !nextTo(si[chesterfields], pi[fox]) {
							continue
						}
						// 12. Kools next to the house where the horse is kept
						if !nextTo(si[kools], pi[horse]) {
							continue
						}
						return Solution{
							DrinksWater: nationalities[houseAt(ni, di[water])],
							OwnsZebra:   nationalities[houseAt(ni, pi[zebra])],
						}
					}
				}
			}
		}
	}
	return Solution{}
}

// houseAt is identity here (house number -> nationality index lookup),
// helper to get the nationality living in house h from perm n inverse.
func houseAt(ni, h int) int {
	for v, hh := range ni {
		if hh == h {
			return v
		}
	}
	return -1
}

